const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const s = lines.join(' ').split(/\s+/).filter(x => x.length)[0];
const n = s.length;
const z = new Array(n).fill(0);
z[0] = n;
let l = 0, r = 0, total = n;
for (let i = 1; i < n; i++) {
  if (i < r) z[i] = Math.min(r - i, z[i - l]);
  while (i + z[i] < n && s[z[i]] === s[i + z[i]]) z[i]++;
  if (i + z[i] > r) { l = i; r = i + z[i]; }
  total += z[i];
}
console.log(total);

